// pillTransforms/index.ts

import { stringFns, type StringFns } from './string'
import type { NowId } from './nowId'
import { mathFns, type MathFns } from './math'
import { dateTimeFns, type DateTimeFns } from './datetime'
import { utilitiesFns, type UtilitiesFns } from './utilities'
import { sanitizeShellFns, type SanitizeShellFns } from './sanitize-shell'
import { sanitizeSqlFns, type SanitizeSqlFns } from './sanitize-sql'
import { complexDataFns, type ComplexDataFns } from './complex-data'

// Types for nowId-aware helpers
interface SanitizeFnsWithId {
    sql: NowId<SanitizeSqlFns>
    shell: NowId<SanitizeShellFns>
}

class Transform {
    // Will check during plugin implementation which one is required withId or withoutId. Added both for evaluation
    // Plain helpers (no nowId param)
    public readonly string: StringFns = stringFns
    public readonly math: MathFns = mathFns
    public readonly dateTime: DateTimeFns = dateTimeFns
    public readonly utilities: UtilitiesFns = utilitiesFns
    public readonly sanitize: { sql: SanitizeSqlFns; shell: SanitizeShellFns } = {
        sql: sanitizeSqlFns,
        shell: sanitizeShellFns,
    }
    public readonly complexData: ComplexDataFns = complexDataFns

    // nowId-aware versions (suffix WithId)
    public readonly stringWithId: NowId<StringFns> = stringFns as any as NowId<StringFns>
    public readonly mathWithId: NowId<MathFns> = mathFns as any as NowId<MathFns>
    public readonly dateTimeWithId: NowId<DateTimeFns> = dateTimeFns as any as NowId<DateTimeFns>
    public readonly utilitiesWithId: NowId<UtilitiesFns> = utilitiesFns as any as NowId<UtilitiesFns>
    public readonly sanitizeWithId: SanitizeFnsWithId = {
        sql: sanitizeSqlFns as any as NowId<SanitizeSqlFns>,
        shell: sanitizeShellFns as any as NowId<SanitizeShellFns>,
    }
    public readonly complexDataWithId: NowId<ComplexDataFns> = complexDataFns as any as NowId<ComplexDataFns>
}

export declare const FDTransform: Transform
